```json
{
  "root_causes": [
    {
      "service": "attractions",
      "fault_kind": "container_memory_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) m, attr_k8s_deployment_name dep, round(avg(value)/1e6,1) rss_mb FROM abnormal_metrics WHERE metric='container.memory.rss' AND attr_k8s_deployment_name='attractions' GROUP BY ALL ORDER BY 1", "claim": "Attractions container RSS jumps from about 25 MB to about 772 MB at 01:56 and stays flat."},
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) m, metric, round(avg(value),2) v FROM abnormal_metrics WHERE attr_k8s_deployment_name='attractions' AND metric IN ('container.cpu.usage','container.memory.usage') GROUP BY ALL ORDER BY 1,2", "claim": "Attractions memory usage rises to about 780 MB while container CPU usage stays at zero."},
        {"kind": "trace", "sql": "SELECT 'norm' p, service_name, count(*) n FROM normal_traces WHERE service_name='attractions' GROUP BY ALL UNION ALL SELECT 'abn', service_name, count(*) FROM abnormal_traces WHERE service_name='attractions' GROUP BY ALL", "claim": "Attractions server spans drop from 521 in normal period to zero in the incident window."},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants') GROUP BY ALL ORDER BY 1", "claim": "Frontend HTTP /cinema, /museums and /restaurants return 500 in about 0.04 ms, with no attractions child call."}
      ]
    },
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT metric, attr_k8s_deployment_name dep, round(avg(value),2) avg_v, min(value) mn, max(value) mx FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='user' GROUP BY ALL", "claim": "User deployment availability is 0 for the whole incident window, versus 1 in normal."},
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) m, attr_k8s_pod_name pod, metric, round(max(value),1) mx FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'user-544%' AND metric IN ('k8s.container.restarts','k8s.container.ready') GROUP BY ALL ORDER BY 1,3", "claim": "User pod user-544b8d4448-dmgn6 is not ready and its restart count climbs from 3 to 6."},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE span_name='user.User/CheckUser' GROUP BY ALL", "claim": "All 200 frontend calls to user.User/CheckUser return Error in about 0.02 ms; user server spans are absent."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "attractions",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants','attractions.Attractions/NearbyCinema') OR span_name LIKE 'attractions%' GROUP BY ALL ORDER BY 1,2", "claim": "Attractions-backed frontend HTTP endpoints fail with 500 while attractions spans disappear."}
      ]
    },
    {
      "from": "user",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE span_name IN ('user.User/CheckUser','HTTP /user') GROUP BY ALL ORDER BY 1,2", "claim": "Frontend CheckUser client calls error and HTTP /user returns 500 during the user outage."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' GROUP BY ALL", "claim": "Frontend logs repeated 'User authentication failed' ERROR entries during the incident."}
      ]
    }
  ]
}
```

